async function poll(check: () => Promise<boolean>, message: string, budget = 15000): Promise<void> {
  const deadline = performance.now() + budget;
  for (;;) {
    assert.ok(performance.now() < deadline, message);
    const ready = await check();
    assert.ok(performance.now() < deadline, message);
    if (ready) return;
    await delay(25);
  }
